'use client';

import type { OpenPkg, SpecExport, SpecExportKind } from '@openpkg-ts/spec';
import { DISPLAY_KIND_ORDER, type DisplayKind, KIND_LABELS } from '@openpkg-ts/spec';
import { APIReferencePage } from '@openpkg-ts/ui/docskit';
import { cn } from '@openpkg-ts/ui/lib/utils';
import { type ReactNode, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { ExportSection } from '@/registry/new-york/components/export-section/export-section';

type ExportKind = DisplayKind;
const KIND_ORDER = DISPLAY_KIND_ORDER;

function getExportTitle(exp: SpecExport): string {
  switch (exp.kind) {
    case 'function':
      return `${exp.name}()`;
    case 'class':
      return `class ${exp.name}`;
    case 'enum':
      return `enum ${exp.name}`;
    default:
      return exp.name;
  }
}

export interface FullAPIReferencePageProps {
  spec: OpenPkg;
  kinds?: SpecExportKind[];
  showFilters?: boolean;
  showTOC?: boolean;
  title?: string;
  description?: ReactNode;
  className?: string;
}

/**
 * Single-page API reference that renders all exports in a scrollable view.
 */
export function FullAPIReferencePage({
  spec,
  kinds,
  showFilters = true,
  showTOC = false,
  title,
  description,
  className,
}: FullAPIReferencePageProps): ReactNode {
  const [activeFilter, setActiveFilter] = useState<ExportKind | 'all'>('all');
  const [activeSection, setActiveSection] = useState<string | null>(null);
  const isScrollingRef = useRef(false);

  const availableKinds = useMemo(() => {
    const kindSet = new Set<ExportKind>();
    for (const exp of spec.exports) {
      const kind = exp.kind as ExportKind;
      if (KIND_ORDER.includes(kind)) kindSet.add(kind);
    }
    return KIND_ORDER.filter((k) => kindSet.has(k));
  }, [spec.exports]);

  const filteredExports = useMemo(() => {
    let exports = spec.exports;
    if (kinds?.length) exports = exports.filter((e) => kinds.includes(e.kind as SpecExportKind));
    if (activeFilter !== 'all') exports = exports.filter((e) => e.kind === activeFilter);

    return exports.sort((a, b) => {
      const kindOrderA = KIND_ORDER.indexOf(a.kind as ExportKind);
      const kindOrderB = KIND_ORDER.indexOf(b.kind as ExportKind);
      if (kindOrderA !== kindOrderB) return kindOrderA - kindOrderB;
      return a.name.localeCompare(b.name);
    });
  }, [spec.exports, kinds, activeFilter]);

  const groupedExports = useMemo(() => {
    const groups = new Map<ExportKind, SpecExport[]>();
    for (const exp of filteredExports) {
      const kind = exp.kind as ExportKind;
      if (!groups.has(kind)) groups.set(kind, []);
      groups.get(kind)?.push(exp);
    }
    return groups;
  }, [filteredExports]);

  useEffect(() => {
    if (typeof window === 'undefined') return;
    const hash = window.location.hash.slice(1);
    if (hash) {
      const timer = setTimeout(() => {
        const element = document.getElementById(hash);
        if (element) {
          isScrollingRef.current = true;
          element.scrollIntoView({ behavior: 'smooth' });
          setActiveSection(hash);
          setTimeout(() => {
            isScrollingRef.current = false;
          }, 1000);
        }
      }, 100);
      return () => clearTimeout(timer);
    }
  }, []);

  useEffect(() => {
    if (!showTOC || typeof window === 'undefined') return;

    const handleIntersect = (entries: IntersectionObserverEntry[]) => {
      if (isScrollingRef.current) return;
      for (const entry of entries) {
        if (entry.isIntersecting && entry.intersectionRatio > 0) {
          const id = entry.target.id;
          setActiveSection(id);
          window.history.replaceState(null, '', `#${id}`);
          break;
        }
      }
    };

    const observer = new IntersectionObserver(handleIntersect, {
      rootMargin: '-20% 0px -70% 0px',
      threshold: 0,
    });

    for (const exp of filteredExports) {
      const element = document.getElementById(exp.id || exp.name);
      if (element) observer.observe(element);
    }

    return () => observer.disconnect();
  }, [showTOC, filteredExports]);

  const handleTOCClick = useCallback((id: string) => {
    const element = document.getElementById(id);
    if (element) {
      isScrollingRef.current = true;
      element.scrollIntoView({ behavior: 'smooth' });
      setActiveSection(id);
      window.history.replaceState(null, '', `#${id}`);
      setTimeout(() => {
        isScrollingRef.current = false;
      }, 1000);
    }
  }, []);

  const defaultDescription = (
    <div>
      {spec.meta.description && <p>{spec.meta.description}</p>}
      {spec.meta.version && (
        <p className="text-sm text-[var(--openpkg-text-muted)] mt-2">Version {spec.meta.version}</p>
      )}
    </div>
  );

  const shouldShowFilters = showFilters && !kinds?.length && availableKinds.length > 1;

  return (
    <div
      className={cn(
        'doccov-full-reference-page not-prose',
        showTOC && 'lg:grid lg:grid-cols-[220px_1fr] lg:gap-8',
        className,
      )}
    >
      {showTOC && (
        <aside className="hidden lg:block">
          <nav className="sticky top-20 max-h-[calc(100vh-6rem)] overflow-y-auto pr-4">
            <h4 className="text-sm font-semibold text-[var(--openpkg-text-primary)] mb-3">
              On this page
            </h4>
            <div className="space-y-4">
              {KIND_ORDER.map((kind) => {
                const exports = groupedExports.get(kind);
                if (!exports?.length) return null;
                return (
                  <div key={kind}>
                    <h5 className="text-xs font-medium text-[var(--openpkg-text-muted)] uppercase tracking-wide mb-2">
                      {KIND_LABELS[kind]}
                    </h5>
                    <ul className="space-y-1">
                      {exports.map((exp) => {
                        const id = exp.id || exp.name;
                        const isActive = activeSection === id;
                        return (
                          <li key={id}>
                            <button
                              type="button"
                              onClick={() => handleTOCClick(id)}
                              className={cn(
                                'block w-full text-left text-sm py-1 px-2 rounded-md transition-colors cursor-pointer truncate',
                                isActive
                                  ? 'bg-[color-mix(in_srgb,var(--openpkg-accent-primary)_10%,transparent)] text-[var(--openpkg-accent-primary)] font-medium'
                                  : 'text-[var(--openpkg-text-muted)] hover:text-[var(--openpkg-text-primary)] hover:bg-[var(--openpkg-bg-secondary)]',
                              )}
                              title={getExportTitle(exp)}
                            >
                              {getExportTitle(exp)}
                            </button>
                          </li>
                        );
                      })}
                    </ul>
                  </div>
                );
              })}
            </div>
          </nav>
        </aside>
      )}

      <div>
        <APIReferencePage
          title={title || spec.meta.name || 'API Reference'}
          description={description || defaultDescription}
        >
          {shouldShowFilters && (
            <div className="flex flex-wrap gap-2 mb-8 -mt-4">
              <button
                type="button"
                onClick={() => setActiveFilter('all')}
                className={cn(
                  'px-3 py-1.5 text-sm rounded-md transition-all cursor-pointer',
                  activeFilter === 'all'
                    ? 'bg-[var(--openpkg-accent-primary)] text-[var(--openpkg-text-on-primary)] font-medium'
                    : 'bg-[var(--openpkg-bg-secondary)] text-[var(--openpkg-text-muted)] hover:text-[var(--openpkg-text-primary)]',
                )}
              >
                All
              </button>
              {availableKinds.map((kind) => (
                <button
                  key={kind}
                  type="button"
                  onClick={() => setActiveFilter(kind)}
                  className={cn(
                    'px-3 py-1.5 text-sm rounded-md transition-all cursor-pointer',
                    activeFilter === kind
                      ? 'bg-[var(--openpkg-accent-primary)] text-[var(--openpkg-text-on-primary)] font-medium'
                      : 'bg-[var(--openpkg-bg-secondary)] text-[var(--openpkg-text-muted)] hover:text-[var(--openpkg-text-primary)]',
                  )}
                >
                  {KIND_LABELS[kind]}
                </button>
              ))}
            </div>
          )}

          {filteredExports.map((exp) => (
            <ExportSection key={exp.id || exp.name} export={exp} spec={spec} />
          ))}

          {filteredExports.length === 0 && (
            <div className="rounded-lg border border-[var(--openpkg-border-subtle)] bg-[var(--openpkg-bg-card)] p-8 text-center">
              <p className="text-[var(--openpkg-text-muted)]">
                {activeFilter !== 'all'
                  ? `No ${KIND_LABELS[activeFilter].toLowerCase()} found.`
                  : 'No exports found in this package.'}
              </p>
              {activeFilter !== 'all' && (
                <button
                  type="button"
                  onClick={() => setActiveFilter('all')}
                  className="mt-3 text-sm text-[var(--openpkg-accent-link)] hover:underline cursor-pointer"
                >
                  Show all exports
                </button>
              )}
            </div>
          )}
        </APIReferencePage>
      </div>
    </div>
  );
}
